    summary: "프로그래밍 가능한 달러가 개방형 스테이블코인과 기관 화폐로 갈리고, 월가 규칙이 디파이 담보로 스며들 위험을 지적한다.",
    content: `JP모건의 JPM 달러가 500억 달러를 돌파했다. 블랙록은 자체 스테이블코인 B-Coin을 만들어 USDC를 결제 수단에서 밀어냈다. Tether는 사실상 미국에서 퇴출당했다.

이 사건들을 따로 보면 뉴스다. 하나의 그림으로 합치면 전쟁이 보인다. 다만 이 전쟁에는 선전포고가 없다.

**왜 규칙이 중요한가**

지폐에는 규칙을 심을 수 없었다. 한번 건넨 만원은 받는 사람이 뭘 사든 상관하지 않는다. 그런데 프로그래밍 가능한 돈은 본질이 다르다. 돈 자체에 조건문을 삽입할 수 있다. 지폐는 중립적이었다. 코드로 만든 돈은 중립적일 수 없다.

**두 진영**

크립토 네이티브 스테이블코인은 누구나 들어와 돗자리를 펴고 장사를 할 수 있는 개방된 국립공원이다.

기관 스테이블코인은 비싼 연회비를 낸 회원만 입장할 수 있는 컨트리클럽이다.

**아무도 의도하지 않은 위험**

Aave가 JPM 달러를 담보로 받는 건 크립토의 항복이 아니다. 그런데 각자의 이익을 따라가다 보면, 결과적으로 디파이의 담보물 대부분이 월가가 발행한 자산으로 채워진다. 이것은 연가시에 감염된 사마귀와 닮아 있다.

그래서 우리에게 필요한 것은 돈을 바라보는 눈을 바꾸는 일이다. 지금 당신의 지갑 안에 들어 있는 돈은 어떤 규칙 위에 올라타 있는가.`,
