export const getPostBySlug = (slug: string): Post | undefined =>
  posts.find((p) => p.slug === slug);

export const getRelatedPosts = (post: Post): Post[] =>
  post.relatedSlugs
    .map((slug) => getPostBySlug(slug))
    .filter(Boolean) as Post[];

export const postsByCategory = (category: Category): Post[] =>
  posts.filter((p) => p.category === category);

export const depthLabel = (depth: DepthLevel): string => {
  const map: Record<DepthLevel, string> = {
    entry: '입구 · 2분',
    mid: '중간 · 5분',
    deep: '심층 · 10분+',
  };
  return map[depth];
};

export const depthColor = (depth: DepthLevel): string => {
  const map: Record<DepthLevel, string> = {
    entry: 'text-green-400 border-green-400/40 bg-green-400/10',
    mid: 'text-yellow-400 border-yellow-400/40 bg-yellow-400/10',
    deep: 'text-red-400 border-red-400/40 bg-red-400/10',
  };
  return map[depth];
};
